     1	package hotel.reservations;
     2	
     3	import hotel.documents.ReservationReceipt;
     4	import hotel.rooms.Room;
     5	import hotel.rooms.Rooms;
     6	import java.math.BigDecimal;
     7	import java.util.List;
     8	
     9	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    10	public final class ReservationService {
    11	
    12	    private final Rooms rooms;
    13	    private final ReservationStore store;
    14	    private final PriceCalculator priceCalculator;
    15	    private final List<ReservationListener> listeners;
    16	
    17	    public ReservationService(Rooms rooms, ReservationStore store, PriceCalculator priceCalculator,
    18	            List<ReservationListener> listeners) {
    19	        this.rooms = rooms;
    20	        this.store = store;
    21	        this.priceCalculator = priceCalculator;
    22	        this.listeners = List.copyOf(listeners);
    23	    }
    24	
    25	    public synchronized Reservation create(NewReservation request) {
    26	        if (!request.checkOut().isAfter(request.checkIn())) {
    27	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    28	        }
    29	        if (request.guests() < 1) {
    30	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    31	        }
    32	        Room room = rooms.find(request.roomNumber())
    33	                .orElseThrow(() -> new HotelException(
    34	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    35	        if (request.guests() > room.capacity()) {
    36	            throw new HotelException(
    37	                    ErrorCode.CAPACITY_EXCEEDED,
    38	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    39	        }
    40	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
    41	            throw new HotelException(
    42	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    43	        }
    44	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
    45	        return store.add(request, price);
    46	    }
    47	
    48	    public Reservation find(long reservationId) {
    49	        return store.find(reservationId)
    50	                .orElseThrow(() -> new HotelException(
    51	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    52	    }
    53	
    54	    /** The guest paid: the reservation is confirmed, and the listeners hear about it. */
    55	    public synchronized Reservation confirm(long reservationId) {
    56	        Reservation reservation = find(reservationId);
    57	        if (reservation.status() != ReservationStatus.PENDING) {
    58	            throw notAllowed(reservation, "confirm");
    59	        }
    60	        reservation.confirmPayment();
    61	        store.update(reservation);
    62	        Room room = roomOf(reservation);
    63	        listeners.forEach(listener -> listener.confirmed(reservation, room));
    64	        return reservation;
    65	    }
    66	
    67	    /**
    68	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    69	     * reservation was never paid, so nothing comes back).
    70	     */
    71	    public synchronized Reservation cancel(long reservationId) {
    72	        Reservation reservation = find(reservationId);
    73	        if (reservation.status() != ReservationStatus.PENDING
    74	                && reservation.status() != ReservationStatus.CONFIRMED) {
    75	            throw notAllowed(reservation, "cancel");
    76	        }
    77	        boolean wasConfirmed = reservation.status() == ReservationStatus.CONFIRMED;
    78	        BigDecimal refund = switch (reservation.ratePlan()) {
    79	            case STANDARD -> reservation.amountPaid();
    80	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
    81	        };
    82	        reservation.cancel(refund);
    83	        store.update(reservation);
    84	        if (wasConfirmed) {
    85	            Room room = roomOf(reservation);
    86	            listeners.forEach(listener -> listener.cancelled(reservation, room));
    87	        }
    88	        return reservation;
    89	    }
    90	
    91	    public synchronized Reservation checkIn(long reservationId) {
    92	        Reservation reservation = find(reservationId);
    93	        if (reservation.status() != ReservationStatus.CONFIRMED) {
    94	            throw notAllowed(reservation, "check in");
    95	        }
    96	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
    97	        store.update(reservation);
    98	        return reservation;
    99	    }
   100	
   101	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   102	    public synchronized ReservationReceipt checkOut(long reservationId) {
   103	        Reservation reservation = find(reservationId);
   104	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   105	            throw notAllowed(reservation, "check out");
   106	        }
   107	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   108	        store.update(reservation);
   109	        return new ReservationReceipt(reservation, roomOf(reservation));
   110	    }
   111	
   112	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   113	    public ReservationReceipt receiptCopy(long reservationId) {
   114	        Reservation reservation = find(reservationId);
   115	        if (!reservation.isPaid()) {
   116	            throw notAllowed(reservation, "issue a receipt for");
   117	        }
   118	        return new ReservationReceipt(reservation, roomOf(reservation));
   119	    }
   120	
   121	    private Room roomOf(Reservation reservation) {
   122	        return rooms.find(reservation.roomNumber()).orElseThrow();
   123	    }
   124	
   125	    private static HotelException notAllowed(Reservation reservation, String operation) {
   126	        return new HotelException(
   127	                ErrorCode.OPERATION_NOT_ALLOWED,
   128	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
   129	    }
   130	}
